insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_107_v1'
from (values
('127.767.c.5',3,'A course syllabus lists skills students should master, such as budgeting, writing reports and communicating with the public. These are the knowledge and skills for the course of study in:','["public management", "pottery making", "stage lighting", "farm equipment repair"]'::jsonb,0,'Courses state knowledge and skills to master.','original'),
('127.767.c.5',4,'In a public management class, the ''knowledge and skills'' section of the standards tells students:','["when the bell rings", "what they are expected to learn and be able to do", "who the school mascot is", "what the lunch menu is"]'::jsonb,1,'Standards list expected learning.','original'),
('127.767.d.1.A',3,'A student charts how a city''s public works department answers to voters and elected boards, while a food bank answers to donors and its own board. This compares and contrasts management of:','["two movie studios", "two restaurants", "government and nonprofit agencies", "two sports teams"]'::jsonb,2,'Accountability differs.','original'),
('127.767.d.1.A',4,'A key difference between a government agency and a nonprofit is that a government agency is funded mainly by:','["product sales", "investor dividends", "ticket sales", "taxes and appropriations"]'::jsonb,3,'Government relies on public funding.','original'),
('127.767.d.1.B',3,'A department posts a mission to protect clean drinking water, then sets goals that support the larger agency''s vision. A student compares:','["department vision, goals and mission to support the agency''s", "colors of department logos", "office furniture", "lunch schedules"]'::jsonb,0,'Department goals support agency mission.','original'),
('127.767.d.1.B',4,'A department''s goals should align with:','["random ideas", "the larger organization''s vision and mission", "a competitor''s plan", "unrelated hobbies"]'::jsonb,1,'Alignment keeps efforts coordinated.','original'),
('127.767.d.2.A',3,'A new parks manager joins a professional association, meets county staff and partners with a school district. This develops:','["closed circles", "private hobbies", "expansive professional networks internally and with other organizations", "isolated work habits"]'::jsonb,2,'Networks aid cooperation.','original'),
('127.767.d.2.A',4,'A benefit of a strong professional network for a public manager is:','["fewer contacts", "less information", "more isolation", "easier sharing of ideas and resources"]'::jsonb,3,'Networks share resources.','original'),
('127.767.d.2.B',3,'A hiring team practices posting jobs in many places and interviewing a wide range of candidates to build a staff reflecting the community. This practices the process of:','["recruiting a diverse workforce", "closing positions", "hiring only friends", "avoiding applicants"]'::jsonb,0,'Diverse recruitment widens the pool.','original'),
('127.767.d.2.B',4,'To recruit a diverse applicant pool, an agency should:','["post only internally", "advertise openings widely and in varied outlets", "hide the opening", "rely on word of mouth"]'::jsonb,1,'Broad outreach.','original'),
('127.767.d.2.C',3,'When two departments clash over shared space, a manager listens, finds common ground and turns the dispute into a joint plan. This applies:','["avoidance to end talks", "silence to wait", "interpersonal skills to manage conflicts positively", "blaming to win"]'::jsonb,2,'Interpersonal skills resolve conflict.','original'),
('127.767.d.2.C',4,'A productive way to handle a workplace conflict is to:','["ignore it", "complain to others", "take a side at once", "listen to both sides and seek common ground"]'::jsonb,3,'Active listening.','original'),
('127.767.d.2.D',3,'A director opens each staff meeting by connecting daily tasks to the agency''s vision, mission and goals. This emphasizes the need to:','["infuse understanding of vision, mission and goals into all work", "separate staff from goals", "hide the mission", "skip planning"]'::jsonb,0,'Mission shapes daily work.','original'),
('127.767.d.2.D',4,'Reminding employees how their tasks support the agency''s mission can:','["confuse priorities", "increase focus and motivation", "reduce clarity", "lower morale"]'::jsonb,1,'Purpose motivates.','original'),
('127.767.d.2.E',3,'A county compares the chance of a flood against the cost of buying insurance and building barriers, then picks a plan. This analyzes the concept of:','["risk denial", "risk creation", "risk management", "risk avoidance only"]'::jsonb,2,'Risk management weighs likelihood and cost.','original'),
('127.767.d.2.E',4,'Risk management includes:','["hiding risks", "ignoring risks", "creating risks", "identifying, assessing and reducing risks"]'::jsonb,3,'The standard steps.','original'),
('127.767.d.2.F',3,'Before voting on the annual budget, a city gives notice of the meeting so residents may attend. This legally publicizes:','["meetings at which budget and allocation decisions will be made", "closed sessions", "secret deals", "private parties"]'::jsonb,0,'Open meeting laws require notice.','original'),
('127.767.d.2.F',4,'Public notice of a budget meeting helps ensure that decisions are:','["made in secret", "made openly with citizen input", "made by one person", "made without input"]'::jsonb,1,'Transparency.','original'),
('127.767.d.3.A',3,'A supervisor finds staff reluctant to share drafts and templates, fearing others will take credit. She sets credit rules and sharing norms. This addresses:','["parking complaints", "lack of lunch breaks", "reluctance of employees to share work product and intellectual property", "dress codes"]'::jsonb,2,'Clear credit norms encourage sharing.','original'),
('127.767.d.3.A',4,'A manager can encourage sharing of work product by:','["hiding credit", "punishing sharing", "banning teamwork", "recognizing and crediting contributors"]'::jsonb,3,'Credit builds trust.','original'),
('127.767.d.3.B',3,'A water engineer explains a new treatment rule to residents using everyday words and a simple chart. This restates complex technical information in:','["language the general public can understand", "code words", "language only engineers know", "legal jargon"]'::jsonb,0,'Plain language aids understanding.','original'),
('127.767.d.3.B',4,'The best way to explain a technical issue to the public is to:','["use long reports", "use plain language and clear examples", "use jargon", "use acronyms only"]'::jsonb,1,'Use plain language.','original'),
('127.767.d.3.C',3,'A city manager explains why the council raised a fee, gives the reasons and answers residents'' questions at a forum. This explains, justifies and discusses:','["private jokes", "recipes", "public issues effectively", "sports trades"]'::jsonb,2,'Explain and justify decisions.','original'),
('127.767.d.3.C',4,'When justifying a public decision, a manager should give:','["personal insults", "no reasons", "only slogans", "clear reasons and supporting facts"]'::jsonb,3,'Reasons build trust.','original'),
('127.767.d.3.D',3,'A spokesperson practices staying calm, answering truthfully and redirecting when a reporter asks a hostile question. This presents techniques to handle:','["difficult interviews and situations", "routine filing", "quiet days", "easy tasks only"]'::jsonb,0,'Prepare for tough questions.','original'),
('127.767.d.3.D',4,'If asked a hostile question in an interview, the best response is to:','["change the subject rudely", "stay calm and answer factually", "refuse to talk", "lose your temper"]'::jsonb,1,'Calm and factual.','original'),
('127.767.d.3.E',3,'A clerk follows the same rules whether a reporter or a resident asks to see a public record. This affords the public:','["preferred access", "no access", "equal opportunity of access to open records", "secret access"]'::jsonb,2,'Open records are equally available.','original'),
('127.767.d.3.E',4,'Under open-records laws, most government records are:','["sold to bidders", "for officials only", "private forever", "available to any member of the public on request"]'::jsonb,3,'Public access.','original'),
('127.767.d.4.A',3,'An analyst pulls budget numbers, staffing counts and service results from a city and from a comparable nonprofit to compare them. This obtains:','["relevant data on public and non-public management", "recipes", "sports scores", "travel photos"]'::jsonb,0,'Gather relevant data.','original'),
('127.767.d.4.A',4,'Relevant data for comparing two agencies could include:','["weather", "budgets, staffing and service outcomes", "favorite colors", "pet names"]'::jsonb,1,'Comparable metrics.','original'),
('127.767.d.4.B',3,'A researcher uses surveys, cost-benefit analysis and trend charts to study a new program. This applies:','["random guessing", "wishful thinking", "pertinent research and analytical methodologies", "hearsay"]'::jsonb,2,'Use sound methods.','original'),
('127.767.d.4.B',4,'A cost-benefit analysis compares a project''s:','["names and dates", "colors and fonts", "songs and videos", "expected costs and expected benefits"]'::jsonb,3,'Costs versus benefits.','original'),
('127.767.d.4.C',3,'Before closing a bus route, a manager studies how many riders it will affect and for what trips. This assesses:','["the impact of probable changes on the public", "a sports score", "last year''s menu", "a parade route"]'::jsonb,0,'Predict public impact.','original'),
('127.767.d.4.C',4,'Before a policy change, managers should consider how it will affect:','["no one", "the people who use the service", "only the budget", "only the managers"]'::jsonb,1,'Impact on users.','original'),
('127.767.d.5.A',3,'A budget analyst prices a new library branch using government accounting standards and consistent categories. This estimates costs according to:','["rumor", "personal opinion", "standards for government accounting", "guesswork"]'::jsonb,2,'Use standard accounting.','original'),
('127.767.d.5.A',4,'Following accounting standards when estimating costs ensures:','["random numbers", "secret numbers", "inflated numbers", "consistent and comparable figures"]'::jsonb,3,'Standards ensure comparability.','original'),
('127.767.d.5.B',3,'A manager presents a low-cost, a mid-cost and a full-service version of a recreation program for the council to choose from. This proposes:','["options over a range of cost requirements", "only one plan", "no plan", "an unlimited plan"]'::jsonb,0,'Options across cost levels.','original'),
('127.767.d.5.B',4,'Giving decision-makers several cost options helps them:','["spend without limits", "choose what fits the available funds", "avoid deciding", "ignore the cost"]'::jsonb,1,'Options fit budgets.','original'),
('127.767.d.5.C',3,'A grants officer scans state and federal programs for money that could pay for new buses. This analyzes government resources to find:','["ways to cut all spending", "reasons to delay", "possibilities for new or increased funding", "rules to avoid"]'::jsonb,2,'Search for grants.','original'),
('127.767.d.5.C',4,'A government grant is money that is generally:','["personal bonuses", "unrestricted gifts", "loans with interest", "awarded for a specific purpose"]'::jsonb,3,'Grants are purpose-specific.','original'),
('127.767.d.5.D',3,'A student lists expected revenues, then allocates amounts to salaries, supplies and equipment for the department. This prepares:','["a budget", "a menu", "a schedule", "a playlist"]'::jsonb,0,'Budgets plan revenues and expenses.','original'),
('127.767.d.5.D',4,'A balanced department budget should ensure that:','["revenue is unknown", "planned spending does not exceed expected revenue", "spending is unlimited", "costs are ignored"]'::jsonb,1,'Balance revenue and spending.','original'),
('127.767.d.6.A',3,'A purchasing clerk helps program staff complete the forms, quotes and approvals needed to buy new computers under agency rules. This demonstrates how to assist staff to:','["hide costs", "avoid purchases", "fulfill procurement requirements", "skip approvals"]'::jsonb,2,'Support staff through procurement.','original'),
('127.767.d.6.A',4,'Procurement rules exist so that public money is spent:','["secretly", "freely", "carelessly", "fairly and with accountability"]'::jsonb,3,'Fair and accountable.','original'),
('127.767.d.6.B',3,'After a vendor misses deliveries, a manager suggests a change to vendor scoring and deadlines. This recommends process changes to improve:','["vendor reliability and performance", "staff parking", "lunch menus", "office music"]'::jsonb,0,'Improve vendor performance.','original'),
('127.767.d.6.B',4,'One way to improve vendor reliability is to:','["stop paying", "set clear performance standards and review them", "ignore late work", "avoid contracts"]'::jsonb,1,'Performance standards.','original'),
('127.767.d.6.C',3,'To attract many qualified bidders for a road project, the agency posts the notice online, in the paper and with trade groups. This determines:','["closed offers", "private messages", "public announcements to elicit vendor interest and bids", "secret invitations"]'::jsonb,2,'Wide notice yields competitive bids.','original'),
('127.767.d.6.C',4,'Advertising a bid widely tends to:','["raise prices", "reduce competition", "hide the project", "increase competition and lower prices"]'::jsonb,3,'Competition helps taxpayers.','original'),
('127.767.d.6.D',3,'A buyer checks that each possible supplier is licensed, insured and in good standing. This identifies:','["sources that match approved vendor criteria", "friends only", "unlicensed sellers", "random sellers"]'::jsonb,0,'Vendors must meet criteria.','original'),
('127.767.d.6.D',4,'An approved vendor list helps an agency by:','["avoiding standards", "ensuring suppliers meet minimum standards", "raising costs", "skipping checks"]'::jsonb,1,'Vetting vendors.','original'),
('127.767.d.6.E',3,'A review team scores every proposal with the same checklist and weighting so no bidder gets a break. This manages an evaluation process that ensures each bid is:','["favored", "ignored", "evaluated fairly and on equal terms", "delayed"]'::jsonb,2,'Consistent criteria.','original'),
('127.767.d.6.E',4,'Using a written scoring rubric for bids helps ensure:','["secrecy", "bias", "favoritism", "fairness and consistency"]'::jsonb,3,'Rubrics standardize.','original'),
('127.767.d.6.F',3,'An agency stores bids securely and shares a bidder''s trade secrets with no competitor while also following open-bid rules. This identifies ways to safeguard:','["proprietary information of bidders and the rights of the agency", "public gossip", "open diaries", "random files"]'::jsonb,0,'Protect confidential info.','original'),
('127.767.d.6.F',4,'A bidder''s pricing formula is sensitive because it is:','["a sports statistic", "proprietary information", "a weather report", "public information"]'::jsonb,1,'Proprietary data stays protected.','original'),
('127.767.d.7.A',3,'A records officer studies retention schedules and the Public Information Act so that she knows what must be released and what must be kept. This maintains thorough familiarity with:','["recipe collections", "movie reviews", "public information requirements and records management", "fashion tips"]'::jsonb,2,'Know the law and procedures.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_107_v1'
from (values
('127.767.d.7.A',4,'A records retention schedule tells an agency:','["where to hold parties", "what to eat", "which songs to play", "how long to keep different records"]'::jsonb,3,'Retention schedules.','original'),
('127.767.d.7.B',3,'A staff member calmly explains the law and reason behind a decision to keep an investigation file confidential when someone asks for it. This identifies how to explain:','["policy background and rationale to persons denied access", "a joke", "an insult", "a secret"]'::jsonb,0,'Explain rationale respectfully.','original'),
('127.767.d.7.B',4,'When denying a records request, the agency should:','["refuse silently", "explain the legal reason and the appeal options", "shame the requester", "ignore the request"]'::jsonb,1,'Explain and inform.','original'),
('127.767.d.7.C',3,'An IT lead compares passwords, locked cabinets and access logs as ways to keep unauthorized people out of sensitive files. This compares:','["ways to speed access for all", "ways to delete logs", "reliable controls to prevent unauthorized access to records", "ways to share passwords"]'::jsonb,2,'Access controls protect records.','original'),
('127.767.d.7.C',4,'Which control best prevents unauthorized access to digital records?','["no logins", "open files", "shared passwords", "unique passwords with access logs"]'::jsonb,3,'Authentication and logging.','original'),
('127.768.d.1.A',3,'In a mock case, a trainee follows up tips, interviews a mock client and checks where leads go to find who might have broken a rule. This investigates potential violators by:','["exploring leads and conducting mock client interviews", "guessing", "avoiding clues", "closing the case"]'::jsonb,0,'Investigators follow leads.','original'),
('127.768.d.1.A',4,'A lead is best described as:','["a legal penalty", "a piece of information that may help solve a case", "a policy statement", "a final verdict"]'::jsonb,1,'Leads guide investigation.','original'),
('127.768.d.1.B',3,'A trainee practices explaining why a witness should cooperate and how a subpoena legally requires records or testimony. This models:','["bribes for answers", "threats to force silence", "persuasive and ethical techniques, such as subpoenas, to gain cooperation", "tricks to mislead"]'::jsonb,2,'Ethical persuasion and legal tools.','original'),
('127.768.d.1.B',4,'A subpoena is a legal order that requires someone to:','["pay a bonus", "leave town", "stop working", "provide testimony or documents"]'::jsonb,3,'Subpoenas compel.','original'),
('127.768.d.1.C',3,'An investigator sorts a pile of papers into those that show the alleged violation and those that are unrelated, setting aside the second group. This identifies and differentiates:','["relevant and irrelevant evidence and information", "old and new songs", "big and small boxes", "red and blue pens"]'::jsonb,0,'Relevance matters.','original'),
('127.768.d.1.C',4,'Evidence is relevant when it:','["is interesting but unrelated", "helps prove or disprove a fact in the case", "fills a folder", "is old"]'::jsonb,1,'Relevance test.','original'),
('127.768.d.1.D',3,'A trainee photographs a document, logs who handled it and stores it sealed so it can be used at a hearing. This examines evidence while:','["altering it", "losing it", "preserving it and observing the rules of evidence", "sharing it freely"]'::jsonb,2,'Chain of custody.','original'),
('127.768.d.1.D',4,'A chain-of-custody log records:','["the weather", "the case outcome", "the lunch order", "who handled evidence and when"]'::jsonb,3,'Tracks handling.','original'),
('127.768.d.1.E',3,'A trainee reviews invoices, payroll and inspection records of a business to see whether the numbers match and the files are complete. This examines:','["business, commercial, industrial and agency records for accuracy and completeness", "fashion catalogs", "comic books", "sports magazines"]'::jsonb,0,'Record review.','original'),
('127.768.d.1.E',4,'A mismatch between invoices and payments might signal:','["good weather", "possible errors or fraud", "normal sunshine", "perfect accuracy"]'::jsonb,1,'Discrepancies deserve review.','original'),
('127.768.d.1.F',3,'In a short case report, a trainee lists what happened in order, avoids opinions and keeps sentences tight. This organizes facts:','["loosely", "emotionally", "accurately, objectively, logically and concisely", "randomly"]'::jsonb,2,'Good reports are factual.','original'),
('127.768.d.1.F',4,'A factual investigative report should avoid:','["dates", "observations", "names", "unsupported opinions"]'::jsonb,3,'Stay objective.','original'),
('127.768.d.1.G',3,'A trainee learns that peeking into someone''s private home or medical file without authority is illegal. This analyzes matters that are prohibited or concern:','["invasion of privacy", "open meetings", "sports rules", "public parades"]'::jsonb,0,'Privacy limits investigators.','original'),
('127.768.d.1.G',4,'An investigator needs a legal basis, such as a warrant, before:','["asking a question", "searching private property", "reading a public sign", "walking in a park"]'::jsonb,1,'Warrants protect privacy.','original'),
('127.768.d.1.H',3,'During a role-play, a trainee watches a mock subject from a distance and notes times, places and actions without interfering. This simulates conducting:','["a parade", "a lesson", "surveillance while recording facts", "a trade fair"]'::jsonb,2,'Surveillance records observations.','original'),
('127.768.d.1.H',4,'Notes taken during surveillance should include:','["guesses", "jokes", "gossip", "dates, times, locations and observed actions"]'::jsonb,3,'Factual notes.','original'),
('127.768.d.2.A',3,'An analyst sees that a project''s actual spending is far above its standard cost and investigates why. This analyzes:','["the common accounting problem of costs deviating from standards", "a color mismatch", "a font mismatch", "a sports mismatch"]'::jsonb,0,'Variance analysis.','original'),
('127.768.d.2.A',4,'When actual costs exceed the standard, the difference is called a:','["tariff", "variance", "bonus", "quota"]'::jsonb,1,'Cost variance.','original'),
('127.768.d.2.B',3,'A regulator compares sharing databases, joint meetings and shared calendars to keep different agencies in step on a case. This compares ways to:','["avoid agencies", "hide information", "coordinate work and organize information with other agencies", "duplicate work"]'::jsonb,2,'Interagency coordination.','original'),
('127.768.d.2.B',4,'Coordinating with other agencies helps by:','["increasing gaps", "adding duplicates", "reducing communication", "avoiding duplicated effort and gaps"]'::jsonb,3,'Coordination.','original'),
('127.768.d.2.C',3,'In a simulation, a spokesperson releases a clear, honest statement about an inspection finding so rumors do not spread. This simulates:','["releasing public information to minimize controversy", "hiding results", "spreading rumors", "blaming others"]'::jsonb,0,'Clear communication reduces controversy.','original'),
('127.768.d.2.C',4,'To minimize controversy when releasing news, an agency should be:','["vague", "timely, accurate and clear", "secretive", "slow"]'::jsonb,1,'Timely, accurate, clear.','original'),
('127.768.d.2.D',3,'After a research team sends its findings, the field office never hears back and cannot act. This identifies problems that arise regarding the:','["flow of rivers", "flow of music", "flow of information after research responses", "flow of traffic"]'::jsonb,2,'Information flow can break.','original'),
('127.768.d.2.D',4,'One cause of poor information flow in an organization is:','["clear instructions", "too many meetings only", "good tools", "unclear reporting channels"]'::jsonb,3,'Unclear channels.','original'),
('127.768.d.2.E',3,'A team sets up a shared dashboard and a weekly update call so field staff and analysts see the same facts. This creates a solution to the problem of:','["information flow and communication", "uniform colors", "lunch scheduling", "parking spots"]'::jsonb,0,'Fix communication gaps.','original'),
('127.768.d.2.E',4,'A simple fix for communication gaps is to:','["avoid updates", "set regular updates and a shared record", "use rumors", "change nothing"]'::jsonb,1,'Regular updates.','original'),
('127.768.d.2.F',3,'A trainee gives an official an accurate, well-sourced briefing on a rule and its likely effects. This demonstrates the ability to:','["guess answers", "use jokes", "present authoritative advice to interested parties", "avoid questions"]'::jsonb,2,'Authoritative advice is sourced.','original'),
('127.768.d.2.F',4,'Advice is authoritative when it is based on:','["rumors", "popularity", "hunches", "verified facts, rules and expertise"]'::jsonb,3,'Facts and expertise.','original'),
('127.768.d.3.A',3,'An analyst reviews inspection results and sees repeated safety lapses in one plant that need discussion with management. This analyzes data to:','["identify matters needing negotiation for resolution", "close the plant", "ignore lapses", "delay inspections"]'::jsonb,0,'Data points to what needs resolution.','original'),
('127.768.d.3.A',4,'Repeated violations in the same plant usually indicate:','["perfect compliance", "a systemic problem needing resolution", "a one-time accident", "no need for action"]'::jsonb,1,'Patterns signal systemic issues.','original'),
('127.768.d.3.B',3,'A class explores examples of firms that falsify records, skip required tests or ignore posted limits. This explores and identifies:','["rule-following", "successful practices", "different noncompliant practices", "best practices"]'::jsonb,2,'Noncompliance takes many forms.','original'),
('127.768.d.3.B',4,'Falsifying inspection records is an example of:','["routine work", "compliance", "good practice", "noncompliance"]'::jsonb,3,'Falsification is noncompliance.','original'),
('127.768.d.3.C',3,'A regulator weighs a warning letter, a fine, a compliance order or court action as fits a violation. This recommends application of:','["administrative and judicial remedies", "bonuses", "prizes", "rewards"]'::jsonb,0,'Remedies range from administrative to judicial.','original'),
('127.768.d.3.C',4,'A fine imposed by an agency without going to court is an example of an:','["criminal sentence", "administrative remedy", "private contract", "judicial remedy"]'::jsonb,1,'Agency fines are administrative.','original'),
('127.768.d.3.D',3,'A trainee writes a sample report on a case so future auditors can handle similar cases the same way. This produces:','["jokes", "menus", "mock reports that provide a basis for handling similar cases or audits", "private diaries"]'::jsonb,2,'Reports set precedent.','original'),
('127.768.d.3.D',4,'A well-written case report helps future auditors by:','["wasting time", "adding confusion", "hiding the facts", "providing a consistent reference"]'::jsonb,3,'Reports guide future work.','original'),
('127.768.d.4.A',3,'An inspector measures a part''s size, watches a machine run and reviews how a product is made at each step. This conducts:','["dimensional, operational and process inspections", "taste tests", "pop quizzes", "fashion shows"]'::jsonb,0,'Types of inspection.','original'),
('127.768.d.4.A',4,'An inspection that checks the size of a manufactured part is a:','["process inspection only", "dimensional inspection", "music inspection", "menu inspection"]'::jsonb,1,'Dimensional = measurements.','original'),
('127.768.d.4.B',3,'An inspector compares measured readings with the limits in the specification and notes any outside the range. This measures:','["colors", "rumors", "compliance with standards, specifications and requirements", "opinions of staff"]'::jsonb,2,'Compare to specs.','original'),
('127.768.d.4.B',4,'A product that measures outside its specification is:','["exempt", "perfect", "in compliance", "out of compliance"]'::jsonb,3,'Out of spec.','original'),
('127.768.d.4.C',3,'A quality inspector tracks defect counts, temperatures and finish across several batches. This monitors:','["a variety of quality characteristics", "game scores", "lunch trends", "hat sizes"]'::jsonb,0,'Monitor quality.','original'),
('127.768.d.4.C',4,'Tracking defects over many batches helps to:','["hide defects", "spot trends and fix causes", "avoid improvement", "ignore data"]'::jsonb,1,'Trend tracking.','original'),
('127.768.d.4.D',3,'A student studies how a small deviation might bring a warning but a large one could shut down a facility or cause injury. This researches:','["maps", "songs", "consequences of degrees of noncompliance", "menus"]'::jsonb,2,'Consequences scale with severity.','original'),
('127.768.d.4.D',4,'Penalties for noncompliance generally increase with:','["office size", "the weather", "the day of the week", "the severity of the violation"]'::jsonb,3,'Severity matters.','original'),
('127.768.d.4.E',3,'Before deciding on a penalty, an investigator reviews past complaints and the conditions in which a violation occurred. This investigates:','["the history and circumstances of violations", "a game score", "last year''s menu", "a travel plan"]'::jsonb,0,'History informs response.','original'),
